export function normalizeForgeLanguage(value: unknown): ForgeLanguage {
  return value === 'pt-BR' ? 'pt-BR' : 'en';
}

export function translateForgeText(value: string, language: ForgeLanguage): string {
  const exact = strings[value];
  if (exact) return exact[language];
  if (language === 'en') {
    const noticeTranslation = portugueseNoticeTranslations[value];
    if (noticeTranslation) return noticeTranslation;
  }
  const documentationSaved = /^Documentação salva em (.+): (\d+) notas criadas; (\d+) notas existentes preservadas\.$/.exec(value);
  if (documentationSaved && language === 'en') return `Documentation saved to ${documentationSaved[1]}: ${documentationSaved[2]} notes created; ${documentationSaved[3]} existing notes preserved.`;
  const documentationSavedEnglish = /^Documentation saved to (.+): (\d+) notes created; (\d+) existing notes preserved\.$/.exec(value);
  if (documentationSavedEnglish && language === 'pt-BR') return `Documentação salva em ${documentationSavedEnglish[1]}: ${documentationSavedEnglish[2]} notas criadas; ${documentationSavedEnglish[3]} notas existentes preservadas.`;
  const checkboxOptionKey = /^Chave da opção (.+)$/.exec(value);
  if (checkboxOptionKey && language === 'en') return `Option key for ${checkboxOptionKey[1]}`;
  const removeCheckboxOption = /^Remover opção (.+)$/.exec(value);
  if (removeCheckboxOption && language === 'en') return `Remove option ${removeCheckboxOption[1]}`;
  const moveCounterUp = /^Mover (.+) para cima$/.exec(value);
  if (moveCounterUp && language === 'en') return `Move ${moveCounterUp[1]} up`;
  const moveCounterDown = /^Mover (.+) para baixo$/.exec(value);
  if (moveCounterDown && language === 'en') return `Move ${moveCounterDown[1]} down`;
  const counterMaximumSaveFailure = /^Falha ao salvar o máximo individual: (.+)$/.exec(value);
  if (counterMaximumSaveFailure && language === 'en') return `Could not save the individual maximum: ${translateForgeText(counterMaximumSaveFailure[1], language)}`;
  const step = /^Step (\d+)$/.exec(value);
  if (step) return language === 'pt-BR' ? `Etapa ${step[1]}` : value;
  const action = /^Action (\d+)$/.exec(value);
  if (action) return language === 'pt-BR' ? `Ação ${action[1]}` : value;
  const lineValue = /^Value (\d+)$/.exec(value);
  if (lineValue) return language === 'pt-BR' ? `Valor ${lineValue[1]}` : value;
  const lineAria = /^Line value (\d+)$/.exec(value);
  if (lineAria) return language === 'pt-BR' ? `Valor da linha ${lineAria[1]}` : value;
  const removeLineValue = /^Remove value (\d+)$/.exec(value);
  if (removeLineValue) return language === 'pt-BR' ? `Remover valor ${removeLineValue[1]}` : value;
  const lineCount = /^(\d+)\/(\d+) values$/.exec(value);
  if (lineCount) return language === 'pt-BR' ? `${lineCount[1]}/${lineCount[2]} valores` : value;
  const lineLabel = /^Line · (.+)$/.exec(value);
  if (lineLabel && language === 'pt-BR') return `Linha · ${lineLabel[1]}`;
  const lineUnsupported = /^(.+) \(unsupported type\)$/.exec(value);
  if (lineUnsupported && language === 'pt-BR') return `${lineUnsupported[1]} (tipo incompatível)`;
  const numberedColumn = /^Coluna (\d+)$/.exec(value);
  if (numberedColumn) return language === 'en' ? `Column ${numberedColumn[1]}` : value;
  const englishNumberedColumn = /^Column (\d+)$/.exec(value);
  if (englishNumberedColumn && language === 'pt-BR') return `Coluna ${englishNumberedColumn[1]}`;
  const numberedTab = /^Aba (\d+)$/.exec(value);
  if (numberedTab) return language === 'en' ? `Tab ${numberedTab[1]}` : value;
  const columnName = /^Column (\d+) name$/.exec(value);
  if (columnName && language === 'pt-BR') return `Nome da coluna ${columnName[1]}`;
  const rowColumn = /^Row (\d+), column (\d+)$/.exec(value);
  if (rowColumn && language === 'pt-BR') return `Linha ${rowColumn[1]}, coluna ${rowColumn[2]}`;
  const regainLabel = /^Recupera: (.+)$/.exec(value);
  if (regainLabel && language === 'en') return `Regain: ${regainLabel[1]}`;
  const missingImage = /^Arquivo não encontrado: (.+)$/.exec(value);
  if (missingImage && language === 'en') return `File not found: ${missingImage[1]}`;
  const unknownBlock = /^Bloco desconhecido preservado: (.+)\.$/.exec(value);
  if (unknownBlock && language === 'en') return `Unknown block preserved: ${unknownBlock[1]}.`;
  const unsupportedBlock = /^Bloco não suportado: (.+)\.$/.exec(value);
  if (unsupportedBlock && language === 'en') return `Unsupported block: ${unsupportedBlock[1]}.`;
  const libraryDetail = /^v(\d+) · (\d+) campos · (\d+) blocos( · migração do Grid antigo ao abrir)?$/.exec(value);
  if (libraryDetail && language === 'en') {
    return `v${libraryDetail[1]} · ${libraryDetail[2]} fields · ${libraryDetail[3]} blocks${libraryDetail[4] ? ' · legacy Grid migration on open' : ''}`;
  }
  const legacyHeight = /^Altura \(linhas — até (.+)\)$/.exec(value);
  if (legacyHeight) return language === 'pt-BR' ? value : `Height (rows — up to ${legacyHeight[1]})`;
  const failed = /^Não foi possível salvar: (.+)$/.exec(value);
  if (failed && language === 'en') return `Could not save: ${translateForgeText(failed[1], language)}`;
  const templateMissing = /^Template not found: (.+)$/.exec(value);
  if (templateMissing) return language === 'pt-BR' ? `Template não encontrado: ${templateMissing[1]}` : value;
  const fieldCreated = /^Field created: (.+)\. You can configure it here or drag it to the canvas\.$/.exec(value);
  if (fieldCreated) return language === 'pt-BR'
    ? `Field criado: ${fieldCreated[1]}. Você pode configurá-lo aqui ou arrastá-lo para o canvas.`
    : value;
  const childBlocks = /^(\d+) bloco\(s\) filho\(s\)\. Adicione conteúdo selecionando este container em “Adicionar dentro de”.$/.exec(value);
  if (childBlocks && language === 'en') return `${childBlocks[1]} child block(s). Add content by selecting this container in “Add inside”.`;
  const restButtons = /^(\d+)\/(\d+) Rest buttons$/.exec(value);
  if (restButtons && language === 'pt-BR') return `${restButtons[1]}/${restButtons[2]} botões de descanso`;
  const restButtonsSimple = /^(\d+) Rest buttons$/.exec(value);
  if (restButtonsSimple && language === 'pt-BR') return `${restButtonsSimple[1]} botões de descanso`;
  const tabsCount = /^(\d+) tab\(s\)$/.exec(value);
  if (tabsCount && language === 'pt-BR') return `${tabsCount[1]} aba(s)`;
  const fieldSelection = /^Select field settings: (.+)$/.exec(value);
  if (fieldSelection && language === 'pt-BR') return `Selecionar configurações do Field: ${fieldSelection[1]}`;
  const reorderField = /^Reorder field (.+)\. Use the arrow keys or drag this handle\.$/.exec(value);
  if (reorderField && language === 'pt-BR') return `Reordenar Field ${reorderField[1]}. Use as setas do teclado ou arraste esta alça.`;
  const linkedFieldAction = /^Edit field · (.+)$/.exec(value);
  if (linkedFieldAction && language === 'pt-BR') return `Editar Field · ${linkedFieldAction[1]}`;
  const templateFieldTitle = /^Template Field · (.+)$/.exec(value);
  if (templateFieldTitle && language === 'pt-BR') return `Field do template · ${templateFieldTitle[1]}`;
  const playerChoices = /^Player choices \((\d+)\/(\d+)\)$/.exec(value);
  if (playerChoices && language === 'pt-BR') return `Escolhas dos jogadores (${playerChoices[1]}/${playerChoices[2]})`;
  const folderDestination = /^Destino: (.+) · leitura em todo o Vault$/.exec(value);
  if (folderDestination && language === 'en') return `Destination: ${folderDestination[1]} · scanning the entire Vault`;
  const englishLibraryDetail = /^v(\d+) · (\d+) fields · (\d+) blocks( · legacy grid migration on open)?$/.exec(value);
  if (englishLibraryDetail && language === 'pt-BR') return `v${englishLibraryDetail[1]} · ${englishLibraryDetail[2]} Fields · ${englishLibraryDetail[3]} blocos${englishLibraryDetail[4] ? ' · migração do Grid antigo ao abrir' : ''}`;
  const upToActions = /^Up to (\d+) actions can be offered; players may pick up to (\d+)\. Without repeats, picks cannot exceed the number of actions\.$/.exec(value);
  if (upToActions && language === 'pt-BR') return `Podem ser oferecidas até ${upToActions[1]} ações; os jogadores podem escolher até ${upToActions[2]}. Sem repetição, não é possível escolher mais ações do que as oferecidas.`;
  const dataCheckSummary = /^(\d+) campos? sem valor · (\d+) propriedades? extras?$/.exec(value);
  if (dataCheckSummary && language === 'en') return `${dataCheckSummary[1]} ${dataCheckSummary[1] === '1' ? 'field' : 'fields'} missing · ${dataCheckSummary[2]} extra ${dataCheckSummary[2] === '1' ? 'property' : 'properties'}`;
  const linkedTemplateMissing = /^O template Forge vinculado não foi encontrado: (.+)\.$/.exec(value);
  if (linkedTemplateMissing && language === 'en') return `The linked Forge template was not found: ${linkedTemplateMissing[1]}.`;
  const duplicateTemplateId = /^Há mais de um \.forgetemplate com o ID (.+)\. Corrija a duplicação antes de editar\.$/.exec(value);
  if (duplicateTemplateId && language === 'en') return `More than one .forgetemplate uses ID ${duplicateTemplateId[1]}. Resolve the duplicate before editing.`;
  const movedTemplate = /^O template foi encontrado em (.+); a referência YAML foi atualizada \(antes: (.+)\)\.$/.exec(value);
  if (movedTemplate && language === 'en') return `The template was found at ${movedTemplate[1]}; the YAML reference was updated (previously: ${movedTemplate[2]}).`;
  const movedTemplateNoRepair = /^O template foi encontrado em (.+), mas não foi possível atualizar automaticamente o caminho no YAML\.$/.exec(value);
  if (movedTemplateNoRepair && language === 'en') return `The template was found at ${movedTemplateNoRepair[1]}, but its YAML path could not be updated automatically.`;
  const tokenFileMissing = /^A imagem (.+) não foi encontrada no Vault\. Corrija o campo image antes de criar o token\.$/.exec(value);
  if (tokenFileMissing && language === 'en') return `Image ${tokenFileMissing[1]} was not found in the Vault. Fix the image field before creating the token.`;
  const tokenFileUnsupported = /^O arquivo (.+) não parece ser uma imagem compatível com tokens\.$/.exec(value);
  if (tokenFileUnsupported && language === 'en') return `File ${tokenFileUnsupported[1]} does not appear to be an image format supported for tokens.`;
  const templateNotFound = /^O template Forge vinculado não foi encontrado: (.+)\.$/.exec(value);
  if (templateNotFound && language === 'en') return `The linked Forge template was not found: ${templateNotFound[1]}.`;
  const dispatchFailure = /^Não foi possível acionar o comando do Atlas: (.+)\. Com a nota aberta, execute “Atlas VTT: Create token from statblock image” na paleta de comandos\.$/.exec(value);
  if (dispatchFailure && language === 'en') return `Could not run the Atlas command: ${dispatchFailure[1]}. With the note open, run “Atlas VTT: Create token from statblock image” from the command palette.`;
  const libraryOpenFailure = /^Statblock Forge: não foi possível abrir uma aba para o template\.$/.exec(value);
  if (libraryOpenFailure && language === 'en') return 'Statblock Forge: could not open a tab for the template.';
  const publishFailure = /^Statblock Forge: falha ao publicar para Atlas: (.+)$/.exec(value);
  if (publishFailure && language === 'en') return `Statblock Forge: could not publish to Atlas: ${translateForgeText(publishFailure[1], language)}`;
  const openRenderFailure = /^Statblock Forge: não foi possível abrir a visualização do statblock\.$/.exec(value);
  if (openRenderFailure && language === 'en') return 'Statblock Forge: could not open the statblock preview.';
  const openTemplateFailure = /^Statblock Forge: não foi possível abrir o template: (.+)$/.exec(value);
  if (openTemplateFailure && language === 'en') return `Statblock Forge: could not open the template: ${openTemplateFailure[1]}`;
  const sourceSubtitle = /^Fonte: (.+) · Template: (.+) · (JSON|Propriedades Markdown)$/.exec(value);
  if (sourceSubtitle && language === 'en') return `Source: ${sourceSubtitle[1]} · Template: ${sourceSubtitle[2]} · ${sourceSubtitle[3] === 'JSON' ? 'JSON' : 'Markdown properties'}`;
  const missingFields = /^Campos ainda sem valor: (.+)\.$/.exec(value);
  if (missingFields && language === 'en') return `Fields without values yet: ${missingFields[1]}.`;
  const ignoredProperties = /^Propriedades ignoradas por não estarem no template: (.+)\.$/.exec(value);
  if (ignoredProperties && language === 'en') return `Properties ignored because they are not in the template: ${ignoredProperties[1]}.`;
  const publishSummary = /^(.+): (.+)\. (.+)$/.exec(value);
  if (publishSummary && language === 'en' && (publishSummary[1] === 'A nota original foi atualizada' || publishSummary[1] === 'Uma nota Markdown foi criada')) {
    return `${translateForgeText(publishSummary[1], language)}: ${publishSummary[2]}. ${publishSummary[3]}`;
  }
  const templatePublishNote = /^O YAML desta mesma nota continua sendo a única fonte dos valores\. O corpo e os demais campos foram preservados\.$/.exec(value);
  if (templatePublishNote && language === 'en') return 'This note’s YAML remains the single source of values. The body and other fields were preserved.';
  const newNoteDetails = /^A nota Markdown criada passa a ser a fonte única dos valores compartilhados por Forge e Atlas; o JSON original permanece apenas como arquivo de importação\.$/.exec(value);
  if (newNoteDetails && language === 'en') return 'The new Markdown note becomes the single source of values shared by Forge and Atlas; the original JSON remains an import file only.';
  const tokenWarning = /^(.+) Para vincular um token existente, use o menu de contexto do token no Atlas e escolha “Link Statblock”\.$/.exec(value);
  if (tokenWarning && language === 'en') return `${tokenWarning[1]} To link an existing token, open its Atlas context menu and choose “Link Statblock”.`;
  if (language === 'en') {
    const dynamicPatterns: Array<[RegExp, (match: RegExpExecArray) => string]> = [
      [/^Já existe um template chamado (.+)\. Escolha outro nome\.$/, (m) => `A template named ${m[1]} already exists. Choose another name.`],
      [/^O ID de template "(.+)" já está sendo usado por outro arquivo \((.+)\)\. Salve como uma nova cópia para gerar um ID exclusivo\.$/, (m) => `Template ID "${m[1]}" is already used by another file (${m[2]}). Save as a new copy to generate a unique ID.`],
      [/^A chave do campo não pode ficar vazia\.$/, () => 'The Field key cannot be empty.'],
      [/^Use de 1 a 40 caracteres: comece com uma letra e use apenas letras, números, _ ou -\.$/, () => 'Use 1–40 characters: start with a letter and use only letters, numbers, _ or -.'],
      [/^A chave "(.+)" não é válida\.$/, (m) => `Key "${m[1]}" is invalid.`],
      [/^A chave "(.+)" é reservada\.$/, (m) => `Key "${m[1]}" is reserved.`],
      [/^A chave "(.+)" é reservada pelo Atlas ou pelo JavaScript\.$/, (m) => `Key "${m[1]}" is reserved by Atlas or JavaScript.`],
      [/^A chave "(.+)" está duplicada \(chaves não diferenciam maiúsculas de minúsculas\)\.$/, (m) => `Key "${m[1]}" is duplicated (keys are case-insensitive).`],
      [/^Há mais de um campo com o significado especial "(.+)"\.$/, (m) => `More than one Field uses the special meaning "${m[1]}".`],
      [/^A chave anterior "(.+)" conflita com outro campo\.$/, (m) => `Former key "${m[1]}" conflicts with another Field.`],
      [/^O campo "(.+)" referencia o campo inexistente "(.+)" em tracks\.max\.$/, (m) => `Field "${m[1]}" references missing Field "${m[2]}" in tracks.max.`],
      [/^O bloco (.+) \((.+)\) referencia o campo inexistente "(.+)" em (.+)\.$/, (m) => `Block ${m[1]} (${m[2]}) references missing Field "${m[3]}" in ${m[4]}.`],
      [/^O bloco (.+) \((.+)\) referencia o campo "(.+)" mais de uma vez\.$/, (m) => `Block ${m[1]} (${m[2]}) references Field "${m[3]}" more than once.`],
      [/^As opções do Field "(.+)" não estão em uma lista válida\.$/, (m) => `The options for Field "${m[1]}" are not a valid list.`],
      [/^A opção (\d+) de "(.+)" possui estrutura inválida\.$/, (m) => `Option ${m[1]} in "${m[2]}" has an invalid structure.`],
      [/^A key da opção (\d+) em "(.+)" é inválida\.$/, (m) => `Option key ${m[1]} in "${m[2]}" is invalid.`],
      [/^A key "(.+)" da opção (\d+) em "(.+)" conflita com (outra opção|um alias)\.$/, (m) => `Key "${m[1]}" for option ${m[2]} in "${m[3]}" conflicts with ${m[4] === 'outra opção' ? 'another option' : 'an alias'}.`],
      [/^Os aliases da opção (\d+) em "(.+)" precisam ser uma lista\.$/, (m) => `Aliases for option ${m[1]} in "${m[2]}" must be a list.`],
      [/^Um alias da opção (\d+) em "(.+)" é inválido\.$/, (m) => `An alias for option ${m[1]} in "${m[2]}" is invalid.`],
      [/^O alias "(.+)" repete a key da própria opção em "(.+)"\.$/, (m) => `Alias "${m[1]}" repeats the option's own key in "${m[2]}".`],
      [/^O alias "(.+)" aparece mais de uma vez na opção (\d+) de "(.+)"\.$/, (m) => `Alias "${m[1]}" appears more than once in option ${m[2]} of "${m[3]}".`],
      [/^O alias "(.+)" da opção (\d+) em "(.+)" conflita com (a key|outro alias) da opção (\d+)\.$/, (m) => `Alias "${m[1]}" for option ${m[2]} in "${m[3]}" conflicts with the ${m[4] === 'a key' ? 'key' : 'another alias'} of option ${m[5]}.`],
      [/^A chave do nome da habilidade em "(.+)" é inválida\.$/, (m) => `The ability name key in "${m[1]}" is invalid.`],
      [/^A chave da descrição da habilidade em "(.+)" é inválida\.$/, (m) => `The ability description key in "${m[1]}" is invalid.`],
      [/^As chaves do nome e da descrição de "(.+)" são iguais \("(.+)"\)\.$/, (m) => `The name and description keys in "${m[1]}" are identical ("${m[2]}").`],
      [/^As Ability Parts de "(.+)" precisam ser uma lista\.$/, (m) => `Ability Parts in "${m[1]}" must be a list.`],
      [/^Há uma Ability Part com estrutura inválida em "(.+)"\.$/, (m) => `An Ability Part in "${m[1]}" has an invalid structure.`],
      [/^Uma Part de "(.+)" está sem chave\.$/, (m) => `A Part in "${m[1]}" has no key.`],
      [/^A chave "(.+)" da Part em "(.+)" é inválida\.$/, (m) => `Key "${m[1]}" for a Part in "${m[2]}" is invalid.`],
      [/^A chave "(.+)" da Part em "(.+)" conflita com uma chave reservada\.$/, (m) => `Key "${m[1]}" for a Part in "${m[2]}" conflicts with a reserved key.`],
      [/^A chave "(.+)" aparece mais de uma vez nas Ability Parts de "(.+)"\.$/, (m) => `Key "${m[1]}" appears more than once in the Ability Parts of "${m[2]}".`],
      [/^A Part "(.+)" em "(.+)" precisa de um nome\.$/, (m) => `Part "${m[1]}" in "${m[2]}" needs a name.`],
      [/^O máximo do Counter "(.+)" precisa ser de 1 a 12\.$/, (m) => `The maximum for Counter "${m[1]}" must be from 1 to 12.`],
      [/^A aparência do Counter "(.+)" precisa ser Pips ou Boxes\.$/, (m) => `The appearance for Counter "${m[1]}" must be Pips or Boxes.`],
      [/^As opções da Part "(.+)" precisam ser uma lista de textos\.$/, (m) => `Options for Part "${m[1]}" must be a list of text values.`],
      [/^A coluna (\d+) da tabela "(.+)" não possui uma slotKey definida\.$/, (m) => `Column ${m[1]} in table "${m[2]}" has no slotKey.`],
      [/^A coluna (\d+) da tabela "(.+)" não possui uma slotKey válida\.$/, (m) => `Column ${m[1]} in table "${m[2]}" has an invalid slotKey.`],
      [/^A slotKey "(.+)" aparece mais de uma vez na tabela "(.+)"\.$/, (m) => `slotKey "${m[1]}" appears more than once in table "${m[2]}".`],
      [/^Há um bloco sem ID válido\.$/, () => 'A block has no valid ID.'],
      [/^O bloco (.+) aponta para o campo inexistente (.+)\.$/, (m) => `Block ${m[1]} references missing Field ${m[2]}.`],
      [/^O bloco (.+) não possui configuração de Grid\.$/, (m) => `Block ${m[1]} has no Grid configuration.`],
      [/^A largura do bloco (.+) precisa ser de 1 a 12 colunas\.$/, (m) => `Block ${m[1]} must be 1–12 columns wide.`],
      [/^A altura do bloco (.+) precisa ser de 1 a (.+) linhas\.$/, (m) => `Block ${m[1]} must be 1–${m[2]} rows high.`],
      [/^O container (.+) precisa possuir uma lista de blocos filhos\.$/, (m) => `Container ${m[1]} must have a child block list.`],
      [/^O container Tabs (.+) só pode conter Sections\.$/, (m) => `Tabs container ${m[1]} can only contain Sections.`],
      [/^Este arquivo não é um template de statblock do Atlas\.$/, () => 'This file is not an Atlas statblock template.'],
      [/^O arquivo atual não pôde ser validado como o template que foi aberto\. Reabra-o antes de salvar\.$/, () => 'The current file could not be validated as the template that was opened. Reopen it before saving.'],
      [/^Dois arquivos de documentação resultam no mesmo nome: (.+)\.$/, (m) => `Two documentation files resolve to the same name: ${m[1]}.`],
      [/^Este template compartilha o ID "(.+)" com outro arquivo \((.+)\)\. Atualizar este arquivo fica bloqueado até resolver a colisão; salvar como cópia gera um ID novo\.$/, (m) => `This template shares ID "${m[1]}" with another file (${m[2]}). Updating this file is blocked until the conflict is resolved; save as a copy to generate a new ID.`],
      [/^O ID de bloco (.+) está duplicado\.$/, (m) => `Block ID ${m[1]} is duplicated.`],
      [/^O caminho (.+) já existe como arquivo\.$/, (m) => `The path ${m[1]} already exists as a file.`],
      [/^O caminho (.+) é um arquivo, não uma pasta\.$/, (m) => `The path ${m[1]} is a file, not a folder.`],
      [/^O destino (.+) já existe e é uma pasta\.$/, (m) => `The destination ${m[1]} already exists as a folder.`],
      [/^A visualização registrada não foi carregada \(view: (.+)\)\.$/, (m) => `The registered view did not load (view: ${m[1]}).`],
      [/^O armazenamento de vínculos do Forge está inválido ou usa uma versão mais recente; ele foi preservado sem alterações\.(.*)$/, (m) => `Forge link storage is invalid or uses a newer version; it was preserved without changes.${m[1]}`],
      [/^Não é possível criar a pasta de statblocks porque "(.+)" é um arquivo\.$/, (m) => `Cannot create the statblock folder because "${m[1]}" is a file.`],
      [/^O campo "(.+)" não pode ser usado em uma ficha Forge\.$/, (m) => `Field "${m[1]}" cannot be used in a Forge statblock.`],
      [/^A chave "(.+)" aparece mais de uma vez no template\.$/, (m) => `Key "${m[1]}" appears more than once in the template.`],
      [/^O campo "(.+)" precisa conter um número válido\.$/, (m) => `Field "${m[1]}" must contain a valid number.`],
      [/^O campo "(.+)" contém JSON inválido\.$/, (m) => `Field "${m[1]}" contains invalid JSON.`],
      [/^O campo "(.+)" precisa receber um objeto JSON\.$/, (m) => `Field "${m[1]}" must receive a JSON object.`],
      [/^O campo "(.+)" precisa receber uma lista JSON\.$/, (m) => `Field "${m[1]}" must receive a JSON array.`],
      [/^O campo "(.+)" mudou desde que o editor foi aberto\. Reabra o editor e tente novamente\.$/, (m) => `Field "${m[1]}" changed after the editor was opened. Reopen the editor and try again.`],
      [/^O significado "(.+)" já está atribuído a outro campo\.$/, (m) => `Meaning "${m[1]}" is already assigned to another field.`],
      [/^Não foi possível restaurar (.+): a chave "(.+)" já está ocupada\.$/, (m) => `Could not restore ${m[1]}: key "${m[2]}" is already in use.`],
      [/^Este campo ainda é usado por fórmulas ou regras: (.+)\. Remova ou reassocie essas dependências antes de excluir o campo\.$/, (m) => `This field is still used by formulas or rules: ${m[1]}. Remove or reassign those dependencies before deleting the field.`],
      [/^Este Field é usado por Dice Formulas \((.+)\)\. Redirecione essas fórmulas antes de alterar seu tipo para (.+)\.$/, (m) => `This Field is used by Dice Formulas (${m[1]}). Redirect those formulas before changing its type to ${m[2]}.`],
      [/^Tipo de campo não suportado: (.+)$/, (m) => `Unsupported field type: ${m[1]}`],
      [/^Tipo de bloco não suportado: (.+)$/, (m) => `Unsupported block type: ${m[1]}`],
      [/^A slotKey "(.+)" já está sendo usada por outra coluna desta tabela\.$/, (m) => `slotKey "${m[1]}" is already used by another column in this table.`],
      [/^Use uma slotKey iniciada por letra, com até 40 caracteres e apenas letras, números, _ ou -\.$/, () => 'Use a slotKey that starts with a letter, is up to 40 characters long, and contains only letters, numbers, _ or -.'],
      [/^A key "(.+)" não é válida\. Use letras minúsculas e números\/_, começando por uma letra\.$/, (m) => `Key "${m[1]}" is invalid. Use lowercase letters and numbers/_, starting with a letter.`],
      [/^O alias "(.+)" não é válido\.$/, (m) => `Alias "${m[1]}" is invalid.`],
      [/^A key\/alias "(.+)" está sendo usada por mais de uma opção deste Field\.$/, (m) => `Key/alias "${m[1]}" is used by more than one option in this Field.`],
      [/^O Resource Atlas "(.+)" mudou desde o cálculo do descanso\. Reabra o descanso e tente novamente\.$/, (m) => `Atlas Resource "${m[1]}" changed after the Rest was calculated. Reopen Rest and try again.`],
      [/^O Resource Atlas "(.+)" possui valores de campanha divergentes entre mapas e precisa ser sincronizado\. Reabra o descanso e tente novamente\.$/, (m) => `Atlas Resource "${m[1]}" has conflicting campaign values across maps and must be synchronized. Reopen Rest and try again.`],
      [/^O Resource Atlas "(.+)" não possui um valor persistível\. Reabra o descanso e tente novamente\.$/, (m) => `Atlas Resource "${m[1]}" has no persistable value. Reopen Rest and try again.`],
      [/^O Resource Atlas "(.+)" mudou após a gravação; o rollback foi interrompido para preservar a alteração mais recente\.$/, (m) => `Atlas Resource "${m[1]}" changed after the write; rollback was stopped to preserve the latest change.`],
      [/^(.+) Além disso, não foi possível reverter o Resource Atlas: (.+)$/, (m) => `${translateForgeText(m[1], language)} In addition, the Atlas Resource could not be rolled back: ${translateForgeText(m[2], language)}`],
      [/^Falha ao salvar a imagem: (.+)$/, (m) => `Could not save the image: ${translateForgeText(m[1], language)}`],
      [/^Falha ao remover a imagem: (.+)$/, (m) => `Could not remove the image: ${translateForgeText(m[1], language)}`],
      [/^Falha ao salvar o enquadramento da imagem: (.+)$/, (m) => `Could not save the image framing: ${translateForgeText(m[1], language)}`],
      [/^Falha ao salvar o campo (.+): (.+)$/, (m) => `Could not save field ${m[1]}: ${translateForgeText(m[2], language)}`],
      [/^Falha ao salvar os valores do statblock: (.+)$/, (m) => `Could not save statblock values: ${translateForgeText(m[1], language)}`],
      [/^Falha ao salvar o máximo individual: (.+)$/, (m) => `Could not save the individual maximum: ${translateForgeText(m[1], language)}`],
      [/^Não foi possível remover o rascunho recuperável: (.+)$/, (m) => `Could not remove the recovery draft: ${translateForgeText(m[1], language)}`],
      [/^Não foi possível salvar uma cópia de recuperação: (.+)$/, (m) => `Could not save a recovery copy: ${translateForgeText(m[1], language)}`],
      [/^Template salvo, mas a cópia de recuperação não pôde ser removida: (.+)$/, (m) => `Template saved, but the recovery copy could not be removed: ${translateForgeText(m[1], language)}`],
      [/^Template salvo\. Atenção: (.+)$/, (m) => `Template saved. Warning: ${translateForgeText(m[1], language)}`],
      [/^Novo template salvo: (.+)$/, (m) => `New template saved: ${m[1]}`],
      [/^Template atualizado: (.+)$/, (m) => `Template updated: ${m[1]}`],
      [/^Statblock Forge: falha ao exportar para Atlas: (.+)$/, (m) => `Statblock Forge: failed to export to Atlas: ${translateForgeText(m[1], language)}`],
      [/^Exportação concluída: (.+)\. Grid, Dense e aparência exclusivos do Forge não são transferidos para o Atlas\.(.*)$/, (m) => `Export completed: ${m[1]}. Forge-only Grid, Dense, and appearance settings are not transferred to Atlas.${translateForgeText(m[2], language)}`],
      [/^Statblock Forge: falha ao publicar para Atlas: (.+)$/, (m) => `Statblock Forge: failed to publish to Atlas: ${translateForgeText(m[1], language)}`],
    ];
    for (const [pattern, format] of dynamicPatterns) {
      const match = pattern.exec(value);
      if (match) return format(match);
    }
    // Translate Atlas compatibility fragments inside export notices without touching user-authored Field labels.
    let atlasCompatibilityTranslation = value
      .replace(/A Ability Part Counter "([^"]+)" será exportada como texto no Atlas \(ex\.: 2\/3\)\. O Forge restaura as marcas e o máximo ao abrir esta mesma nota\./g,
        (_match, label: string) => `The Ability Part Counter "${label}" will be exported as text in Atlas (e.g. 2/3). Forge restores its markers and maximum when this same note is opened.`)
      .replace(/O campo "([^"]+)" usa o tipo "([^"]+)", que não está no formato verificado do Atlas\. O valor será preservado no arquivo, mas o Atlas pode ignorá-lo ou tratá-lo como texto\./g,
        (_match, label: string, type: string) => `The field "${label}" uses type "${type}", which is not in the verified Atlas format. Its value will be preserved in the file, but Atlas may ignore it or treat it as text.`)
      .replace(/A Ability Part "([^"]+)" usa o tipo desconhecido "([^"]+)"\. Ele será mantido sem conversão; o Atlas pode interpretá-lo como texto\./g,
        (_match, label: string, type: string) => `The Ability Part "${label}" uses the unknown type "${type}". It will be kept without conversion; Atlas may interpret it as text.`)
      .replace(/O bloco "([^"]+)" não pertence ao catálogo verificado do Atlas\. Sua estrutura será preservada, mas a renderização nativa pode ignorá-lo\./g,
        (_match, block: string) => `The block "${block}" is not part of the verified Atlas catalog. Its structure will be preserved, but native rendering may ignore it.`)
      .replace(/Grid Dense, dimensões físicas, temas e cores individuais por bloco são exclusivos do Forge e não são aplicados pelo renderer do Atlas\. Esses ajustes permanecem no \.forgetemplate ou no sidecar Forge associado ao template\./g,
        'Grid Dense, physical dimensions, themes, and per-block colors are Forge-only and are not applied by the Atlas renderer. These settings remain in the .forgetemplate or its associated Forge sidecar.')
      .replace(/Os tipos de campos e Ability Parts foram reconhecidos pelo formato Atlas verificado\./g,
        'Field and Ability Part types match the verified Atlas format.')
      .replace('Avisos de compatibilidade:', 'Compatibility warnings:');
    if (atlasCompatibilityTranslation !== value) return atlasCompatibilityTranslation;

    // Translate known Portuguese fragments in composed notices after pattern-specific
    // handling, so a translated fragment cannot prevent a full-message pattern from matching.
    let composedTranslation = value;
    for (const [portuguese, english] of Object.entries(portugueseNoticeTranslations)) {
      if (composedTranslation.includes(portuguese)) {
        composedTranslation = composedTranslation.replaceAll(portuguese, english);
      }
    }
    if (composedTranslation !== value) return composedTranslation;
  }
  return value;
}

/** Localizes editor-owned labels and helper text without changing the preview's user content. */
export function localizeForgeElement(root: HTMLElement, language: ForgeLanguage): void {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      let parent = node.parentElement;
      while (parent && parent !== root) {
        if (parent.classList.contains('statblock-forge__canvas-sheet') || parent.classList.contains('statblock-forge__user-content')) return NodeFilter.FILTER_REJECT;
        parent = parent.parentElement;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const nodes: Text[] = [];
  while (walker.nextNode()) if (walker.currentNode instanceof Text) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const source = node.nodeValue ?? '';
    const trimmed = source.trim();
    if (!trimmed) continue;
    const translated = translateForgeText(trimmed, language);
    if (translated !== trimmed) node.nodeValue = source.replace(trimmed, translated);
  }

  for (const element of [root, ...Array.from(root.querySelectorAll<HTMLElement>('*'))]) {
    if (element !== root && (element.closest('.statblock-forge__canvas-sheet') || element.closest('.statblock-forge__user-content'))) continue;
    for (const attribute of ['title', 'placeholder', 'aria-label']) {
      const current = element.getAttribute(attribute);
      if (current) element.setAttribute(attribute, translateForgeText(current, language));
    }
  }
}
